(function(){function renderFallback(def,target){var pre=document.createElement("pre");pre.className="mermaid-fallback";pre.textContent=def.trim();target.innerHTML="";target.appendChild(pre);return {svg:pre.outerHTML}};window.mermaid={initialize:function(){},render:function(id,definition,cb,container){var target=container||document.createElement("div");var result=renderFallback(definition,target);if(typeof cb==="function"){cb(result.svg);}return Promise.resolve(result);},run:function(){document.querySelectorAll(".mermaid").forEach(function(node){renderFallback(node.textContent||"",node);});}};})(); 
